125	 * terminator run, or at the end of the text. A lone period after a known
126	 * abbreviation does not end a sentence.
127	 *
128	 * @param {string} text
129	 * @returns {number}
130	 */
131	function sentenceCount(text) {
132	  assertText('sentenceCount', text);
133	  let count = 0;
134	  let start = 0;
135	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
136	    const before = text.slice(start, match.index);
